@extends('layouts.app') @section('content')<div class="page-head"><h1>New Job Card</h1></div><div class="panel form-panel"><form method="post" action="{{ route('jobs.store') }}">@csrf<div class="form-grid"><label>Customer*<select name="customer_id" id="customerSelect" required onchange="filterVehicles()">@foreach($customers as $c)<option value="{{ $c->id }}">{{ $c->full_name }} — {{ $c->phone }}</option>@endforeach</select></label><label>Vehicle*<select name="vehicle_id" id="vehicleSelect" required><option value="">Select Customer First</option>@foreach($vehicles as $v)<option value="{{ $v->id }}" data-customer="{{ $v->customer_id }}" @selected(request('vehicle_id')==$v->id)>{{ $v->registration_number }} — {{ $v->make }} {{ $v->model }}</option>@endforeach</select></label><label>Priority*<select name="priority"><option>normal</option><option>urgent</option><option>vip</option><option>waiting_customer</option><option>breakdown</option></select></label><label class="wide">Customer complaint<textarea name="customer_complaint"></textarea></label><fieldset class="wide"><legend>Requested services</legend><div class="checks">@foreach($services as $s)<label class="check"><input type="checkbox" name="service_ids[]" value="{{ $s->id }}"> {{ $s->name }} — Rs. {{ number_format($s->base_price,2) }}</label>@endforeach</div></fieldset></div><button class="primary">Create Job Card</button></form></div>

<script>const vehiclesData=@json($vehicles);function filterVehicles(){const customerId=document.getElementById('customerSelect').value;const vehicleSelect=document.getElementById('vehicleSelect');const currentSelected=vehicleSelect.value;vehicleSelect.innerHTML='<option value="">Select Vehicle</option>';if(customerId){const customerVehicles=vehiclesData.filter(v=>v.customer_id==customerId);customerVehicles.forEach(v=>{const option=document.createElement('option');option.value=v.id;option.textContent=v.registration_number+' — '+v.make+' '+v.model;if(v.id==currentSelected)option.selected=true;vehicleSelect.appendChild(option);});}}</script>@endsection
